(6556954, 976543, 65234, '<td valign="top">Wow; this guy just jumps off the screen!  Nice, nice detail.</td>', 'Wow; this guy just jumps off the screen!  Nice, nice detail.', '2011-10-01 14:35:14.000000', NULL, 1),
(6556957, 973104, 65234, '<td valign="top">Beautiful light and DOF!  Really, really nice.</td>', 'Beautiful light and DOF!  Really, really nice.', '2011-10-01 14:35:25.000000', NULL, 1),
(6556958, 976795, 65234, '<td valign="top">Love the water highlights reflecting off the bird''s breast.  Sweet portrait.</td>', 'Love the water highlights reflecting off the bird''s breast.  Sweet portrait.', '2011-10-01 14:35:35.000000', NULL, 1),
(6556959, 976445, 65234, '<td valign="top">I can''t believe you made me laugh at one bug eating another!  But that pose is just too funny!</td>', 'I can''t believe you made me laugh at one bug eating another!  But that pose is just too funny!', '2011-10-01 14:35:41.000000', NULL, 1),
(6556960, 973005, 65234, '<td valign="top">Aw, that''s really sweet!</td>', 'Aw, that''s really sweet!', '2011-10-01 14:35:44.000000', NULL, 1),
(6556961, 974997, 65234, '<td valign="top">Love those little flowers in the foreground!  Adds a lot to the progression up into the colder heights.  I might desaturate some of the cyan-colored snow.</td>', 'Love those little flowers in the foreground!  Adds a lot to the progression up into the colder heights.  I might desaturate some of the cyan-colored snow.', '2011-10-01 14:36:22.000000', NULL, 1),
(6556962, 976045, 65234, '<td valign="top">More misty than dark, but definitely lovely.  The big, old tree in the foreground is a perfect foil to the softer woods behind.</td>', 'More misty than dark, but definitely lovely.  The big, old tree in the foreground is a perfect foil to the softer woods behind.', '2011-10-01 14:36:32.000000', NULL, 1),
(6556963, 974830, 65234, '<td valign="top">The backlit dog is gorgeous.  Love the tones in this.  I might crop just a bit tighter on top and eliminate the overhanging tree to give the dog more prominence.</td>', 'The backlit dog is gorgeous.  Love the tones in this.  I might crop just a bit tighter on top and eliminate the overhanging tree to give the dog more prominence.', '2011-10-01 14:36:39.000000', NULL, 1),
(6556964, 975620, 65234, '<td valign="top">Great stop-motion on that honeybee!</td>', 'Great stop-motion on that honeybee!', '2011-10-01 14:36:42.000000', NULL, 1),
(6556965, 976827, 65234, '<td valign="top">Perfectly lovely exposure on this scene.</td>', 'Perfectly lovely exposure on this scene.', '2011-10-01 14:36:45.000000', NULL, 1),
(6556966, 976267, 65234, '<td valign="top">Soft and subtle and mysterious.</td>', 'Soft and subtle and mysterious.', '2011-10-01 14:36:47.000000', NULL, 1),
(6556967, 975971, 65234, '<td valign="top">Love the eye contact!  Well captured.</td>', 'Love the eye contact!  Well captured.', '2011-10-01 14:36:54.000000', NULL, 1),
(6556968, 971958, 65234, '<td valign="top">Perfect timing to get the waterfowl in that last patch of sunlight.  Nice composition and colors.</td>', 'Perfect timing to get the waterfowl in that last patch of sunlight.  Nice composition and colors.', '2011-10-01 14:36:58.000000', NULL, 1),
(6556969, 972947, 65234, '<td valign="top">Great capture.</td>', 'Great capture.', '2011-10-01 14:37:08.000000', NULL, 1),
(6556970, 972025, 65234, '<td valign="top">Lunch break!  Mama looks patient, maybe a bit resigned.  Like the DOF here.</td>', 'Lunch break!  Mama looks patient, maybe a bit resigned.  Like the DOF here.', '2011-10-01 14:37:10.000000', NULL, 1),
(6556971, 976651, 65234, '<td valign="top">Looks like a hairy clam sitcking its tongue out at me!  What an odd-looking thing.</td>', 'Looks like a hairy clam sitcking its tongue out at me!  What an odd-looking thing.', '2011-10-01 14:37:13.000000', NULL, 1),
(6556972, 973554, 65234, '<td valign="top">That is not at all what I was expecting from the thumb!  Thought it was a land/seascape.  This is MUCH more interesting.</td>', 'That is not at all what I was expecting from the thumb!  Thought it was a land/seascape.  This is MUCH more interesting.', '2011-10-01 14:37:21.000000', NULL, 1),
(6556973, 976052, 65234, '<td valign="top">Nicely titled :-)  Very pretty grasshopper; looks like he has little shoes on his many feet.  Nice detail and DOF.</td>', 'Nicely titled :-)  Very pretty grasshopper; looks like he has little shoes on his many feet.  Nice detail and DOF.', '2011-10-01 14:37:26.000000', NULL, 1),
(6556974, 975937, 65234, '<td valign="top">Very cool effect!</td>', 'Very cool effect!', '2011-10-01 14:37:28.000000', NULL, 1),
(6556975, 976681, 65234, '<td valign="top">:-(  Particularly pitiful posture (I''m apparently in an alliterative mood).</td>', ':-(  Particularly pitiful posture (I''m apparently in an alliterative mood).', '2011-10-01 14:37:31.000000', NULL, 1),
(6556976, 976743, 65234, '<td valign="top">Very pretty.  So much busy life in all the little lights, and the remembrance of lives gone too soon in the skyward beams.</td>', 'Very pretty.  So much busy life in all the little lights, and the remembrance of lives gone too soon in the skyward beams.', '2011-10-01 14:37:34.000000', NULL, 1),
(6556977, 974733, 65234, '<td valign="top">I should feel sorry for the mosquito ... except that it''s a bloodsucking little mosquito.  Pretty web it''s stuck in.</td>', 'I should feel sorry for the mosquito ... except that it''s a bloodsucking little mosquito.  Pretty web it''s stuck in.', '2011-10-01 14:37:39.000000', NULL, 1),
(6556978, 972351, 65234, '<td valign="top">What a well-feathered fellow!  Quirky pose.</td>', 'What a well-feathered fellow!  Quirky pose.', '2011-10-01 14:37:42.000000', NULL, 1),
(6556979, 976317, 65234, '<td valign="top">Made me smile!  Nice detail on all those fishes.</td>', 'Made me smile!  Nice detail on all those fishes.', '2011-10-01 14:37:45.000000', NULL, 1),
(6556980, 975066, 65234, '<td valign="top">Much to see here.</td>', 'Much to see here.', '2011-10-01 14:38:04.000000', NULL, 1),
