(6559879, 976623, 108580, '<td valign="top">Super indoor architectural image. Not detracting from the quality but its off horison 1 degree clockwise to the right.</td>', 'Super indoor architectural image. Not detracting from the quality but its off horison 1 degree clockwise to the right.', '2011-10-04 03:43:02.000000', NULL, 1),
(6559882, 976598, 108580, '<td valign="top">It could be :) Oh wait, everyone here thinks NG only publish wild animals.</td>', 'It could be :) Oh wait, everyone here thinks NG only publish wild animals.', '2011-10-04 03:43:50.000000', NULL, 1),
(6559891, 976345, 108580, '<td valign="top">Stunning detailed BiF.</td>', 'Stunning detailed BiF.', '2011-10-04 04:32:28.000000', NULL, 1),
(6559892, 976651, 28427, '<td valign="top">Minimalistic. The pure white back- and underground allows full attention on  the autumn colors of the chestnut.  The chestnut itself has something of an open mouth from some kind of creature with its tongue sticking out.  Even the interior of the "mouth" is perfectly detailed.</td>', 'Minimalistic. The pure white back- and underground allows full attention on  the autumn colors of the chestnut.  The chestnut itself has something of an open mouth from some kind of creature with its tongue sticking out.  Even the interior of the "mouth" is perfectly detailed.', '2011-10-04 04:53:43.000000', NULL, 1),
(6559893, 976681, 28427, '<td valign="top">Seeing this I wonder who was the little girl that played her mommy, is she missing her, does she cries over her loss, where is she.  Beautiful b&amp;w, the raindrops, the leafs and other stuff complete this photograph.</td>', 'Seeing this I wonder who was the little girl that played her mommy, is she missing her, does she cries over her loss, where is she.  Beautiful b&w, the raindrops, the leafs and other stuff complete this photograph.', '2011-10-04 04:55:53.000000', NULL, 1),
(6559894, 976052, 28427, '<td valign="top">He nearly looks like a toy, with all his beautiful vivid colors.  Nice and crisp.  You were lucky with such a colorful background.</td>', 'He nearly looks like a toy, with all his beautiful vivid colors.  Nice and crisp.  You were lucky with such a colorful background.', '2011-10-04 04:57:37.000000', NULL, 1),
(6559895, 973104, 28427, '<td valign="top">Great detail, nice light.  Makes you dive in the flower like a bee.  Actually, now that I think of it: this is actually how bees see them (even bigger)</td>', 'Great detail, nice light.  Makes you dive in the flower like a bee.  Actually, now that I think of it: this is actually how bees see them (even bigger)', '2011-10-04 04:59:58.000000', NULL, 1),
(6559897, 976863, 28427, '<td valign="top">So elegant, almost fragile as he''s hanging there.  Typical way to \"hang out\" for them. Who would think that they''re such strength in their body.<br/>Well captured</td>', 'So elegant, almost fragile as he''s hanging there.  Typical way to \"hang out\" for them. Who would think that they''re such strength in their body.Well captured', '2011-10-04 05:03:34.000000', NULL, 1),
(6559898, 976664, 32011, '<td valign="top">This looks more like the Split Point Lighthouse at Airey''s Inlet than it does the one at Cape Nelson... but I could be wrong (wouldn''t be a first).<br/> <br/>A beautiful image.  Wonderful composition and colour... perhaps a tad dark in the foreground (if I was to nit pick)... excellent job.</td>', 'This looks more like the Split Point Lighthouse at Airey''s Inlet than it does the one at Cape Nelson... but I could be wrong (wouldn''t be a first). A beautiful image.  Wonderful composition and colour... perhaps a tad dark in the foreground (if I was to nit pick)... excellent job.', '2011-10-04 05:22:18.000000', NULL, 1),
(6559910, 976681, 2337, '<td valign="top">My favorite so far.  Nice range, well composed and tells a story.  Great capture.  Congrats</td>', 'My favorite so far.  Nice range, well composed and tells a story.  Great capture.  Congrats', '2011-10-04 06:55:21.000000', NULL, 1),
(6559912, 973066, 2337, '<td valign="top">I found the background distracting.  Did you try any with a shallow depth of field?</td>', 'I found the background distracting.  Did you try any with a shallow depth of field?', '2011-10-04 06:57:38.000000', NULL, 1),
(6559913, 976314, 2337, '<td valign="top">I like the use of DOF...  Adding smoke might have made this exceptional, although I''m unsure how it could have been achieved...  Just a thought</td>', 'I like the use of DOF...  Adding smoke might have made this exceptional, although I''m unsure how it could have been achieved...  Just a thought', '2011-10-04 07:01:02.000000', NULL, 1),
