(6561728, 973964, 113142, '<td valign="top">cropping off of more of the bottom would have done a lot to bring this into a sleeker ratio, suggesting higher speed (as if that really needed to be emphasized more, right?). Very sharp!</td>', 'cropping off of more of the bottom would have done a lot to bring this into a sleeker ratio, suggesting higher speed (as if that really needed to be emphasized more, right?). Very sharp!', '2011-10-05 18:53:58.000000', NULL, 1),
(6561729, 976787, 113142, '<td valign="top">handheld longish exposure (1/4, 1/6) ? This is a nice picture, maybe a tripod would have made the whole scene more sharp</td>', 'handheld longish exposure (1/4, 1/6) ? This is a nice picture, maybe a tripod would have made the whole scene more sharp', '2011-10-05 18:58:26.000000', NULL, 1),
(6561732, 976864, 113142, '<td valign="top">It is difficult for me to figure out why you felt motion was necessary. Impressionism?</td>', 'It is difficult for me to figure out why you felt motion was necessary. Impressionism?', '2011-10-05 19:00:38.000000', NULL, 1),
