(6569929, 973851, 100393, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=859062" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_859062.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_859062.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/100000-104999/100393/120/Copyrighted_Image_Reuse_Prohibited_859062.jpg"/></a> <br/> <br/>Awarded for the September 2011 Free Study.</td>', '  Awarded for the September 2011 Free Study.', '2011-10-17 09:40:52.000000', NULL, 0),
(6569995, 974840, 19825, '<td valign="top">I just had to revisit the Laughing Woman after seeing that Paul had put it up on the PH thread. First, the score is a bit of a disappointment. This deserved much better. However, the comments are <b><i>incredible</i></b>. I have an Apple entry in voting now sitting at 6.4 with 3 pleasant comments. I would trade it in a heartbeat for this 5.7 image with 32 comments. Gyaban is a very talented guy, and he may be the master of producing images with broad appeal. But, there is plenty he could learn from studying Melethia''s portfolio. Beautiful shot.</td>', 'I just had to revisit the Laughing Woman after seeing that Paul had put it up on the PH thread. First, the score is a bit of a disappointment. This deserved much better. However, the comments are incredible. I have an Apple entry in voting now sitting at 6.4 with 3 pleasant comments. I would trade it in a heartbeat for this 5.7 image with 32 comments. Gyaban is a very talented guy, and he may be the master of producing images with broad appeal. But, there is plenty he could learn from studying Melethia''s portfolio. Beautiful shot.', '2011-10-17 11:30:02.000000', NULL, 0),
(6570025, 973402, 96751, '<td valign="top">Foreground bokeh is SO underrated.  And SO tough to do well in an action shot!</td>', 'Foreground bokeh is SO underrated.  And SO tough to do well in an action shot!', '2011-10-17 11:59:27.000000', NULL, 0),
